#!/usr/bin/env python3
"""protein/de_novo_binder_pipeline — auto-generated run.py (archetype=mutation_scan).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "mutation_scan"
BRAIN = "protein"
SKILL = "de_novo_binder_pipeline"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'batch_id': '...', 'n_designs_input': 1000, 'n_designs_passed_5metric': 47, 'designs': [{'design_id': 'B0042', 'structure_path': '....pdb', 'sequence': 'MKLA...', 'metrics': {'pLDDT_binder': 82.5, 'pAE_interaction': 7.8, 'iPTM': 0.71, 'Rosetta_ddG': -32.4, 'SAP_score': 8.5, 'MPNN_sequence_recovery': 0.34}, 'passed_5metric': True, 'rank': 1}], 'in_silico_to_in_vitro_estimate': '5-15% (per protein-002, protein-010)', 'specificity_panel_results': [], 'provenance': {}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """RFdiffusion de novo binder design(给 target,生成结合 binder)。"""
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    target_pdb = payload.get("target_pdb")
    hotspots = payload.get("hotspots", "")  # e.g. "A30,A33,A56"
    binder_len = int(payload.get("binder_length", 80))
    num = int(payload.get("num_designs", 4))
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="rfdiff_binder_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "RFdiffusion", "target": target_pdb,
                   "hotspots": hotspots, "binder_len": binder_len, "out_dir": out_dir}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "wt_score": 0.0, "scan_csv": "",
                "top_mutations": [], "diagnostics": {**diagnostics, "dry": True}}
    if not target_pdb or not _os.path.isfile(target_pdb):
        return {"ok": False, "error": f"target_pdb 不存在", "diagnostics": diagnostics}
    # 默认 A1-9999 假设 target 链 A 从残基 1 起;真实 PDB(如 1iep 链 A=225-498)残基号不从 1
    # 开始时 RFdiffusion contig 解析器会 assert 失败。允许 payload 用 contigs 显式指定真实范围。
    contigs = payload.get("contigs") or f"A1-9999/0 {binder_len}-{binder_len}"  # target chain + binder
    cmd = ["run_inference.py",
           f"inference.input_pdb={target_pdb}",
           f"contigmap.contigs=[{contigs}]",
           f"ppi.hotspot_res=[{hotspots}]",
           f"inference.num_designs={num}",
           f"inference.output_prefix={_os.path.join(out_dir, 'binder')}"]
    t0 = _time.time()
    r = run_tool(cmd, timeout=int(payload.get("timeout_s", 3600)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "RFdiffusion binder 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    import glob as _glob
    pdbs = sorted(_glob.glob(_os.path.join(out_dir, "binder_*.pdb")))
    return {"ok": True, "skill_id": SKILL, "wt_score": 0.0, "scan_csv": "",
            "top_mutations": [{"position": 0, "from_aa": "", "to_aa": "",
                              "ddg": 0.0, "design_pdb": p} for p in pdbs[:10]],
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": {**diagnostics, "designs": pdbs}}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
